answer:
```sparql
PREFIX ex: <http://example.com/>
PREFIX chm: <http://example.com/CHM/>
PREFIX pro: <http://example.com/PRO/>
SELECT DISTINCT ?property WHERE {
  # 获取Chemical Composition的性能指标（PRO类型）
  ?row_pm ex:hasSubject chm:Chemical%20Composition ;
          ex:hasObject ?perf .
  FILTER(STRSTARTS(STR(?perf), 'http://example.com/PRO/'))

  # 匹配与性能指标相关或协同影响性能指标的物理性质
  {
    # 物理性质作为主体，关系为related to或synergistically influence
    ?row_rel ex:hasSubject ?property ;
             ex:hasObject ?perf ;
             ex:hasRelationship ?rel .
    FILTER(LCASE(STR(?rel)) IN ("related to", "synergistically influence"))
  }
  UNION
  {
    # 对称关系related to的反向匹配
    ?row_rel ex:hasSubject ?perf ;
             ex:hasObject ?property ;
             ex:hasRelationship ?rel .
    FILTER(LCASE(STR(?rel)) = "related to")
  }

  # 确保结果为物理性质（PRO类型）且排除性能指标本身
  FILTER(STRSTARTS(STR(?property), 'http://example.com/PRO/'))
  FILTER(?property != ?perf)
}
```

